import random
_lw = list(dict.fromkeys(LONG.split())); random.Random(7).shuffle(_lw)
for i in range(20):
    T.append((f"G{i+1:02d}", "Long Haul", " ".join(_lw[i::20])))
used = set(json.load(open('/tmp/claude-1000/-home-logstar-code-github-funlikely-puchi-shichigo/36e3ca03-cb83-47e7-90a8-d2b456079ce4/scratchpad/used.json')))
for b in ('batch-005', 'batch-006'):
    used |= {e['answer'] for r in json.load(open(f'../../content/generated/{b}.json')) for e in r['clueAnswers']}
import tiling as Tl, lexicon as lx
def nugly(x):
    g = Tl.good_tilings(x)
    return 9 if not g else sum(lx.ugly_boundaries(t, i == 0, i == len(g[0]) - 1) for i, t in enumerate(g[0]))
def ugly(x):
    g = Tl.good_tilings(x)
    return not g or any(lx.ugly_boundaries(t, i == 0, i == len(g[0]) - 1) for i, t in enumerate(g[0]))
out, vet = [], []
for fid, th, ws in T:
    w = [x for x in dict.fromkeys(ws.split()) if x not in used and 5 <= len(x) <= 10]
    w = [x for x in w if nugly(x) <= (0 if fid[0] == 'G' else 1)]
    if fid[0] != 'G':
        vet += w
    out.append({"id": fid, "category": "mixed" if fid[0] == 'G' else "themed", "theme": th,
                "allowProperNouns": fid[0] != 'G', "words": w})
json.dump(out, open('work/manual_sets-007.json', 'w'), indent=1)
p = 'data/vetted_words.txt'; s = open(p).read(); have = set(s.split())
new = [x.lower() for x in dict.fromkeys(vet) if x.lower() not in have]
if new and '--write-vet' in sys.argv:
    open(p, 'a').write('# batch 007 fandom rounds\n' + '\n'.join(new) + '\n')
for m in out:
    print(m['id'], len(m['words']), ' '.join(m['words']))
